{"code":"import random

def generate(rng):
    # A rectangular array of 2x2 rooms separated by full blue-gray walls.
    nr = rng.randint(3, 6); nc = rng.randint(3, 6)
    h, w = 3*nr-1, 3*nc-1
    g = [[0]*w for _ in range(h)]
    for r in range(2, h, 3):
        for c in range(w): g[r][c] = 6
    for c in range(2, w, 3):
        for r in range(h): g[r][c] = 6
    # objects occupy complete room interiors, as in the example
    cells=[(r,c) for r in range(nr) for c in range(nc)]
    five=rng.choice(cells)
    remaining=[x for x in cells if x!=five]
    k=rng.randint(2, min(5,len(remaining)))
    ones=rng.sample(remaining,k)
    for rr,cc in [five]:
        for dr in (0,1):
            for dc in (0,1): g[3*rr+dr][3*cc+dc]=5
    for rr,cc in ones:
        for dr in (0,1):
            for dc in (0,1): g[3*rr+dr][3*cc+dc]=1
    return g"}

